"""Shared aggregate patch/sweep assembly with exact original mouth welding.

Only the path-reader view changes for aggregate ownership. The qualified patch,
original sweep, dimensional law, separator and assembly guards remain intact.
"""
import hashlib
import bpy
from . import aggregate_mouth_nodes, curved_network_surface_nodes
from .curved_quad_fair_nodes import assign_group


def _port_view(original):
    """Keep the exact dimensional source reader with an explicit kind-4 guard."""
    c=curved_network_surface_nodes.c
    name='Prochitecture Streets / Aggregate span view v1 / '+hashlib.sha256(original.name.encode()).hexdigest()[:16]
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for s in original.interface.items_tree:
        if s.item_type=='SOCKET':g.socket(s.name,s.socket_type,s.in_out,default=getattr(s,'default_value',None))
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    call=g.node('GeometryNodeGroup','Unchanged original dimensional path');call.node_tree=original
    kind=c._read(g,inp.outputs['Ports'],'st_pp_kind',inp.outputs['Index'],'INT')
    valid=g.math('COMPARE',kind,4.)
    for s in call.inputs:
        value=inp.outputs[s.name]
        if s.name=='Ports':value=c._store(g,value,'st_pp_kind',0,'INT')
        g.bind(value,s)
    for s in call.outputs:
        g.bind(c.V(g,s)*valid if s.name=='Valid' else s,out.inputs[s.name])
    return g.g


def build(patch, *, separators=True, dimensions=True, separator_quality=True, overlapping_bundles=True):
    original = curved_network_surface_nodes.build(external=True, local_frames=True,
        dimensions=dimensions, port_paths=True, interpolation=True,
        separators=separators, free_ended_separators=separators, aggregate_patch=patch,
        separator_quality=separator_quality and separators, aggregate_unions=overlapping_bundles and separators)
    memo = {}

    def visit(tree):
        if tree in memo:
            return memo[tree]
        if tree == patch or tree.name.startswith('Prochitecture Streets / Aggregate path view v1'):
            return tree
        if tree.name.startswith('Prochitecture Streets / Prepared original port approach v1'):
            result = aggregate_mouth_nodes.approach(interpolation='Exact or smooth' in tree.name)
        elif tree.name.startswith('Prochitecture Streets / Original Section-end port path v3'):
            result = _port_view(tree)
        elif 'mapped original span source v3' in tree.name and 'Authored transition identity' not in tree.name:
            from . import curved_dimension_corridor_nodes
            result = visit(curved_dimension_corridor_nodes.port_source(interpolation=True,authored=True))
        else:
            children = [(n.name, visit(n.node_tree)) for n in tree.nodes if n.type == 'GROUP' and n.node_tree]
            changes = [(key, child) for key, child in children if tree.nodes[key].node_tree != child]
            result = tree.copy() if changes else tree
            if changes:
                result.name = 'Prochitecture Streets / Aggregate network v1 / '+hashlib.sha256(tree.name.encode()).hexdigest()[:16]
                for key, child in changes:
                    assign_group(result.nodes[key], child)
        memo[tree] = result
        return result

    result = visit(original)
    result['st_aggregate_network_candidate'] = 1
    return result
